const NUMRE=/^\s*\d+\s*[.．、)）]\s*/;
function parseCardLines(t){return String(t||'').split('\n').map(x=>x.trim()).filter(Boolean).map(l=>{const m=l.match(NUMRE);return m?{text:l.slice(m[0].length).trim(),num:parseInt(m[0],10)+'.',ni:parseInt(m[0],10)}:{text:l,num:''}}).filter(o=>o.text)}
function sortByNum(l){return l.length>1&&l.every(o=>o.ni!=null)?l.map((o,i)=>({o,i})).sort((x,y)=>(x.o.ni-y.o.ni)||(x.i-y.i)).map(z=>z.o):l}
