function addCommit(list,base){const cache={};let n=0;list.forEach(e=>{let id=e.cat;if(!id){const k=e.newName;if(!cache[k]){let g=S.cats.find(x=>base&&x.sc===base.sc&&kc(x)===kc(base)&&x.own===base.own&&x.name===k);if(!g){g={id:uid(),sc:base.sc,kind:base.kind||'card',name:k,on:1,as:(base.as||[]).slice(),own:base.own};if(base.big)g.big=base.big;S.cats.push(g)}cache[k]=g.id}id=cache[k]}S.cards.push({id:uid(),cat:id,text:e.text,on:1});n++});
  save();closeSheet();render();toast(n?'已添加 '+n+' 條':'沒有新增（全部重複）')}
function addEntries(ents,base){const dups=[],seenNew={};
  const scopeIds=b=>new Set(S.cats.filter(x=>x.sc===b.sc&&kc(x)===kc(b)&&x.own===b.own).map(x=>x.id));
  ents.forEach(e=>{const b=e.cat?S.cats.find(x=>x.id===e.cat):base,sk=b?(b.sc+'|'+kc(b)+'|'+(b.own||'')):'?';if(!seenNew[sk])seenNew[sk]=new Map();
    const prev=seenNew[sk].get(e.text);if(prev){dups.push({orig:{label:prev.label,text:prev.text},dup:e,oe:prev.e,internal:1,del:'n'});return}
    seenNew[sk].set(e.text,{label:e.num||'',text:e.text,e});
    if(!b)return;const ids=scopeIds(b),hit=S.cards.filter(k=>ids.has(k.cat)&&k.text===e.text);
    if(hit.length){const k0=hit[0],g=S.cats.find(x=>x.id===k0.cat),idx=S.cards.filter(k=>k.cat===k0.cat).indexOf(k0)+1;dups.push({orig:{label:(g&&g.id!==e.cat?esc(g.name)+' ':'')+idx+'.',text:k0.text},dup:e,oldIds:hit.map(k=>k.id),del:'o'})}});
  if(!dups.length){addCommit(ents,base);return}
  pendDup={all:ents,base,dups};dupSheet()}
