  bk:'<path d="M4 8h16v11H4zM3 5h18v3H3z"/><path d="M9 12h6M12 10v5m-2-2 2 2 2-2"/>',
  rs:'<path d="M4.5 10A8 8 0 1 1 5 16"/><path d="M4.5 4v6h6"/><path d="M12 8v4l2.5 1.5"/>',
  dc:'<path d="M12 3 19 6v5c0 4.5-2.8 7.8-7 10-4.2-2.2-7-5.5-7-10V6z"/><path d="m8.5 12 2.2 2.2 4.8-5"/>',
