const settingIcon=id=>`<span class="si" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round">${SICON[id]||SICON.r3}</svg></span>`;
const prr=(k,n)=>`<div class="sr"><span>${n}</span><b id="o-${k}">${S.set[k]}%</b></div><input type="range" min="0" max="100" step="5" value="${S.set[k]}" data-k="${k}">`;
const sList=()=>{const q=sQ.trim();const rows=q?SETS.flatMap(t=>t[1]).filter(r=>(r[0]+r[1]).includes(q)):SETS[sTab][1];return rows.length?'<div class="card" style="padding:0">'+rows.map(r=>(r[2].startsWith('bg')||r[2].startsWith('cx'))?`<div class="srow" data-a="srow" data-i="${r[2]}">${settingIcon(r[2])}<b style="font-weight:400;font-size:calc(16px*var(--fz,1))">${r[0]}</b><span class="grow"></span><span style="color:var(--soft)">›</span></div>`:r[2]==='tc'?`<div class="srow">${settingIcon(r[2])}<b style="font-weight:400;font-size:calc(16px*var(--fz,1))">${r[0]}</b><span class="grow"></span><input type="color" class="color-input" id="tc" value="${S.ink||'#5f5b8d'}" style="width:48px;padding:2px"><button class="btn color-reset" data-a="tcx" style="padding:6px 12px;font-size:calc(12px*var(--fz,1))">還原</button></div>`:`<div class="srow" data-a="srow" data-i="${r[2]}">${settingIcon(r[2])}<b style="font-weight:400;font-size:calc(16px*var(--fz,1))">${r[0]}</b><span class="pill" data-a="shelp" data-i="${r[2]}">功能說明</span><span class="grow"></span><span style="color:var(--soft)">›</span></div>`).join('')+'</div>':'<div class="empty">'+(q?'沒有符合的設置項。':'這裡還沒有項目，之後會增加。')+'</div>'};
const RULES='<div style="font-size:calc(14px*var(--fz,1));line-height:1.9"><p style="margin:0 0 8px"><b>Pearla 的隨機系統遵守以下規則：</b></p><p>① 每次字卡抽取都獨立進行。</p><p>② 所有符合條件的字卡，被抽中的機會完全相同。</p><p>③ 不排除重複結果，同一張字卡可以連續被抽到。</p><p>④ 不因連續抽到相同結果而調整機率。</p><p>⑤ 不設置保底或補償機制。</p><p>⑥ 不刻意平均分配結果。</p><p>⑦ 每一種互動的機率各自獨立判定。</p><p>⑧ 每項設定的數值只影響它所對應的那項互動。</p><p>⑨ 不根據你輸入的文字做語意分析。</p><p>⑩ 不根據之前的互動結果改變後續機率。</p><p>⑪ 被動回覆在發送訊息後先等 6 秒，6 秒過後才開始判定是否已讀不回；主動發送則在「最短時間」到「最長時間」之間隨機選一個時間，時間到了才判定發送取消機率；不論取消或發送，都要等到最長時間結束，才會開始下一次的隨機時間，所以最短到最長時間之間只會有一次主動發送流程。</p><p>⑫ 等待回覆期間不會預先選字卡，等待時間結束後才抽取並立即傳送；一旦抽出就一定會傳送，不會再做第二次「要不要傳」的判定。</p><p>⑬ 同一次回覆有多條時，所有字卡在同一時間抽好，但每隔 3 秒（暫定）才發送下一條。</p><p>⑭ 每條字卡的情緒、心意等判定各算各的，不受同一輪其他字卡影響。</p><p>⑮ emoji與顏文字：每選擇一條字卡後，會先等待設置的「選擇emoji時間」或「選擇顏文字時間」，時間結束才依各自的機率判定要不要加入。兩者的等待時間分開計算，先等emoji或先等顏文字完全隨機；抽中的emoji或顏文字會隨機出現在該條字卡的開頭或結尾，機率各一半。聊天室被動回覆、主動發送與聯絡人發布朋友圈都依照此規則。</p><p>⑯ 各類提醒、他的問題、他的吐槽都是額外發送的訊息，不佔用主動發送的字卡機率與次數。</p><p>⑰ 每日留言會在每日 0 點開始抽取；若抽取失敗，會在「最短抽取時間」～「最長抽取時間」之間隨機等待一段時間後再次抽取。若當時未開啟網頁，則於開啟網頁後立刻開始抽取；同一天重複開啟網頁不會重置或重新判定，必須等到已儲存的抽取時間結束。每天 0 點會重新建立當天的抽取時間段，不沿用前一天的時間段；抽取成功後，當天不再繼續抽取。</p><p>⑰-1 禮拜日例外：若學習進度開啟，禮拜日 0 點後先進行學習進度流程（判定、逐欄修改熟練條），整個流程結束後（含判定失敗或不變化），當天的每日留言才開始抽取；學習進度關閉、或不是禮拜日時，每日留言照常在 0 點開始。</p><p>⑱ 狀態會在程式開啟後開始計時，每到設定的抽取時間才判定一次是否更改狀態；重複開啟程式不會重置計時，必須等到設定時間結束後才會再次判定。若判定成功，會從狀態字卡中隨機抽取並顯示在聊天室名稱下方。</p><p>⑲ 所有計時以目前選定的聊天對象為單位，每個對象各自保存下一次狀態判定時間。</p><p>⑳ 引用消息：每一條回覆在選擇字卡之前，都會先依照設定的機率判定一次是否引用消息。判定成功時，會從你發出的最後 10 條訊息中隨機挑選一條來引用，掛在這一條回覆上。</p><p>㉑ 表情包：每一輪回覆都會依照設定的機率判定一次是否發送表情包；判定成功時，會從可抽取的表情包中隨機抽取一個，隨機插在本輪任一則回覆的前面或後面，所有可插入位置的機率完全相同（例如只有一則回覆時，插在它前面或後面的機率各一半）。</p><p>㉒ 拍一拍：每一輪回覆在「回覆最短時間」到「回覆最長時間」的等待結束後，才依照設定的機率判定一次是否拍一拍；判定成功時，會從可抽取的拍一拍（共用加上該聯絡人專屬）中隨機抽取一條，每一條被抽中的機會完全相同，並排在本輪所有回覆的最前面發出。拍一拍是額外發送的訊息，不佔用字卡的條數；若沒有可抽取的拍一拍，這一輪就不會拍。判定為已讀不回的那一輪不回覆，也不會拍一拍；主動發送同樣依拍一拍機率判定一次。</p><p>㉓ 聯絡人發布朋友圈：聯絡人會在「發布朋友圈時間」的最短與最長範圍內隨機選一個時間，時間到了才判定要不要發文。判定成功後，先依「選擇字卡時間」隨機等待一段時間，結束才開始抽取字卡；字卡抽取完畢，才依「選擇表情包時間」隨機等待，結束後依機率判定是否抽取表情包，判定成功才開始隨機抽取；表情包抽取完畢，再依「選擇貼紙時間」隨機等待，結束後依機率判定是否抽取貼紙，判定成功才開始隨機抽取，並在「放置貼紙時間」結束後，把貼紙放到貼圖牆上的隨機位置。全部選擇完成後才會一起發布到朋友圈。</p><p>㉔ 字卡、表情包、貼紙的數量不會事先決定，而是各自開始抽取時才決定，抽完才知道各有幾個。若聯絡人沒有任何表情包與貼紙可用，就不會發布貼圖牆。</p><p>㉕ 貼圖回覆：你在貼圖牆上貼了貼紙後，聯絡人會先等「判定是否回覆貼紙時間」，時間到再依機率判定要不要回覆；判定成功後，會在「選擇貼紙時間」的範圍內隨機等待一段時間才抽取貼紙；抽取完畢再等「放置貼紙時間」，貼紙會依序（每貼完一個隔 1 秒再貼下一個）出現在貼圖牆上的任意位置，也可能蓋在表情包或你的貼紙上。貼在聯絡人的貼文上，由該聯絡人回覆；貼在自己空間的貼圖牆上，由目前選定的聊天對象回覆。</p><p>㉖ 提取字卡與回覆的順序（被動回覆）：你發送訊息後，聯絡人先判定是否已讀不回。判定為已讀不回，就不會觸發提取字卡流程，也不會進入回覆流程；判定不是已讀不回，才開始整個提取字卡流程（等待判定時間 → 觸發機率判定 → 提取延遲 → 發送提取字卡），這個流程結束後（發送成功、判定失敗、沒有可提取的內容或功能關閉都算結束）才開始回覆字卡流程（等待輸入時間 → 發送字卡）。主動發送（含點聯絡人頭像的拍一拍）沒有已讀不回判定，維持第一則字卡訊息實際發出後才開始提取字卡流程；被動回覆與主動發送各有一份獨立的提取字卡設置。</p></div>';
const NOVA='<div style="font-size:calc(14px*var(--fz,1));line-height:1.9"><p style="margin:0 0 10px"><b>Nova 式回覆</b>是「連著說的話併成一輪再回」的回覆方式，讓對方看起來像真的在讀你的話、想一想再回。</p><p>① 一輪只排一次隊：你連著發的幾句話併成同一輪，每位聯絡人各自只排一次隊。</p><p>② 骰子只擲一次：已讀不回、回幾條，在這一輪開始時擲定，之後補的句子不會重擲；拍一拍則在回覆等待時間結束後才判定一次；引用消息則在每一條回覆選擇字卡前各判定一次。</p><p>③ 到點時間：發送後先等 6 秒，沒有已讀不回，才從「回覆最短時間」到「回覆最長時間」之間隨機抽一個等待時間。</p><p>④ 補一句往後推：你每多補一句，到點時間往後推 1.5 秒，一輪最多替你多等 12 秒。</p><p>⑤ 各排各的：每位聯絡人各有自己的一輪，切去別的聯絡人發訊息，不會頂掉原本那一輪的計時。</p><p>⑥ 已讀不回：發送 6 秒後才開始判定；若擲到，小字當下就出現、這一輪不再回覆；沒擲到才開始抽等待時間與字卡。擲到已讀不回後會進入「已讀不回鎖定時間」（可在設置調整，默認 60 秒），這段時間內你發的訊息都會直接已讀不回。</p><p>⑦ 回覆內容：每一條都從字卡抽取，並在每條字卡抽取後，各自等待選擇時間再依 emoji、顏文字的機率決定要不要添加；表情包則是每一輪判定一次，成功就額外發送一個，並隨機插在任一則回覆的前面或後面；每次抽取獨立、機會均等。</p></div>';
function rulesHtml(q){q=(q||'').trim();if(!q)return RULES;const ps=RULES.match(/<p[^>]*>[\s\S]*?<\/p>/g)||[],ql=q.toLowerCase(),re=new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'gi'),hit=ps.filter(x=>x.replace(/<[^>]+>/g,'').toLowerCase().includes(ql));if(!hit.length)return '<div class="empty">沒有符合的內容。</div>';return '<div style="font-size:calc(14px*var(--fz,1));line-height:1.9">'+hit.map(x=>x.replace(/(<[^>]+>)|([^<]+)/g,(m,t,y)=>t||y.replace(re,'<mark>$&</mark>'))).join('')+'</div>'}
const rCard=q=>'<div class="card set">'+rulesHtml(q)+'</div>';
const THEMES=Object.keys(THEME_DEFS).map(k=>[k,THEME_DEFS[k].name,THEME_DEFS[k].swatch]);
function pickTheme(k,tone){const nm=(THEMES.find(t=>t[0]===k)||[])[1];askChange('主題為「'+nm+'」'+(S.set.keepBg?'':'（背景會一併還原）'),'all',()=>{S.dmPrev=null;S.themeFonts=S.themeFonts||{};S.themeFonts[curTheme()]=S.font||'';if(!S.set.keepFont)S.font=S.themeFonts[k]||'';S.theme=k;if(tone)S.jtone=tone;else if(S.jtone==='dark')S.jtone=(THEME_DEFS[k].tones||[['blue']])[0][0];S.ink='';S.line='';S.shadow='';if(!S.set.keepBg){S.bgColors={all:'#f6f2ff'};S.bgs={};S.bgAll='';S.bg=''}applyTheme();save();render()})}
/* 深色模式種類：每個主題可在「主題」頁按月亮選擇；預設黑貓用「黑貓・深色」，其他主題用「手帳・黑灰」 */
function thmoonRefresh(th){closeSheet();toast('已設定',1200)}
const DARKS=[['journal:dark','手帳・黑灰','journal','dark'],['cat:dark','黑貓・深色','cat','dark'],['moon','月眠','moon','']];
const darkKey=th=>{const d=(S.darkPick||{})[th];return d&&DARKS.some(x=>x[0]===d)?d:(th==='cat'?'cat:dark':'journal:dark')};
const isDark=()=>(['journal','cat'].includes(curTheme())&&S.jtone==='dark')||(curTheme()==='moon'&&!!S.dmPrev);
/* 深色模式＝切到該主題設定的深色種類；再按一次回到原本的主題、配色、字色與背景（存在 S.dmPrev） */
function toggleDark(){
  if(isDark()){const p=S.dmPrev;S.dmPrev=null;
    if(p&&THEME_DEFS[p.theme]){S.theme=p.theme;S.jtone=p.jtone||'blue';S.ink=p.ink||'';S.line=p.line||'';S.shadow=p.shadow||'';if(p.bg){S.bgColors=p.bg.bgColors;S.bgs=p.bg.bgs;S.bgAll=p.bg.bgAll;S.bg=p.bg.bg}}
    else if(curTheme()==='cat'){S.jtone='light';S.ink='';S.line='';S.shadow=''}
    else{S.theme='journal';S.jtone='blue';S.ink='';S.line='';S.shadow=''}}
  else{const dk=DARKS.find(x=>x[0]===darkKey(curTheme()))||DARKS[0];
    S.dmPrev={theme:curTheme(),jtone:S.jtone,ink:S.ink,line:S.line,shadow:S.shadow,bg:S.set.keepBg?null:{bgColors:S.bgColors,bgs:S.bgs,bgAll:S.bgAll,bg:S.bg}};
    S.theme=dk[2];if(dk[3])S.jtone=dk[3];S.ink='';S.line='';S.shadow='';
    if(!S.set.keepBg){S.bgColors={all:'#f6f2ff'};S.bgs={};S.bgAll='';S.bg=''}}
  applyTheme();save();render()}
const DM_ICON={sound:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4z"/><path d="M15.5 8.5a5 5 0 0 1 0 7M18.2 5.8a9 9 0 0 1 0 12.4"/></svg>',mute:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4z"/><path d="m16 9 5 6M21 9l-5 6"/></svg>',sun:'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4.2"/><path d="M12 2.8v2.4M12 18.8v2.4M2.8 12h2.4M18.8 12h2.4M5.5 5.5l1.7 1.7M16.8 16.8l1.7 1.7M5.5 18.5l1.7-1.7M16.8 7.2l1.7-1.7"/></svg>',moon:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 14.2A8.3 8.3 0 0 1 9.8 4a8.3 8.3 0 1 0 10.2 10.2z"/></svg>'};
function punctCard(){const l=ensurePunct(),tot=l.reduce((a,p)=>a+(+p.w>0?+p.w:0),0);
  return '<div class="card set"><h3>標點符號</h3><p class="hint" style="margin:0 0 8px">聊天室回覆裡，字卡與字卡之間會依權重隨機放一個標點（前一張已經有句尾標點就不再加）。權重越大越容易抽到，0 代表不抽；新加的標點預設權重 10。</p>'+
  (l.length?l.map((p,i)=>'<div class="sr" style="align-items:center"><span class="pun-t">'+esc(p.t)+'<small>'+(tot&&+p.w>0?Math.round(+p.w/tot*100)+'%':'0%')+'</small></span><span style="display:flex;gap:6px;align-items:center"><input type="number" inputmode="decimal" min="0" data-pw="'+i+'" value="'+(+p.w)+'" style="width:64px;text-align:right;padding:6px 8px"><button class="btn" style="width:auto;margin:0;padding:6px 10px" data-a="pundel" data-i="'+i+'" aria-label="刪除標點">×</button></span></div>').join(''):'<div class="empty" style="padding:8px 0">目前沒有標點，會固定用「。」。</div>')+
  '<div class="sr" style="align-items:center;margin-top:10px;gap:8px"><input id="punt" maxlength="6" placeholder="新增標點，例如 ～" style="flex:1;min-width:0"><input id="punw" type="number" inputmode="decimal" min="0" value="10" style="width:64px;text-align:right"><button class="btn s" style="width:auto;margin:0;flex:none" data-a="punadd">新增</button></div></div>'}
